export class Validator {
  constructor() {}

  isEmail(email: string): boolean {
    const regex = /^[a-zA-Z0-9._%+-]+@[a-zA-Z0-9.-]+\.[a-z]{2,}$/;
    return regex.test(email);
  }
  isValidPhone(phone: string): boolean {
    const regex = /^[6-9]\d{9}$/;
    return regex.test(phone);
  }
  isStrongPassword(password: string): boolean {
    const regex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[\W_]).{8,}$/;
    return regex.test(password);
  }
  isValidUsername(username: string): boolean {
    const regex = /^[a-zA-Z0-9_]{3,16}$/;
    return regex.test(username);
  }
  isValidURL(url: string): boolean {
    const regex = /^(https?:\/\/)?([\w\d\-]+\.){1,}[\w]{2,}(\/.*)?$/;
    return regex.test(url);
  }
  isValidPincode(pincode: string): boolean {
    const regex = /^\d{6}$/;
    return regex.test(pincode);
  }
  isAlphabetic(str: string): boolean {
    const regex = /^[A-Za-z]+$/;
    return regex.test(str);
  }
  isNumeric(str: string): boolean {
    const regex = /^\d+$/;
    return regex.test(str);
  }
  isEmptyOrWhitespace(str: string): boolean {
    return str.trim().length === 0;
  }
  isValidLength(str: string, min: number, max: number): boolean {
    return str.length >= min && str.length <= max;
  }
  isValidDateFormat(date: string, format: string): boolean {
    const formatMap: Record<string, string> = {
      DD: "(0[1-9]|[12][0-9]|3[01])",
      MM: "(0[1-9]|1[0-2])",
      YYYY: "\\d{4}",
      YY: "\\d{2}",
    };

    // Escape separators like '/', '.', or '-'
    const escapedFormat = format.replace(/[-\/.]/g, (match) => `\\${match}`);

    // Convert format to regex
    const regexPattern = escapedFormat.replace(
      /(DD|MM|YYYY|YY)/g,
      (match) => formatMap[match]
    );
    const regex = new RegExp(`^${regexPattern}$`);

    return regex.test(date);
  }

  customValidation(value: string, pattern: RegExp): boolean {
    const result = pattern.test(value);
    return result;
  }

  isIPAddress(ip: string): boolean {
    const regex =
      /^(25[0-5]|2[0-4]\d|1\d{2}|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d{2}|[1-9]?\d)){3}$/;
    return regex.test(ip);
  }

  isJSON(str: string): boolean {
    try {
      JSON.parse(str);
      return true;
    } catch {
      return false;
    }
  }

  isCreditCard(card: string): boolean {
    const regex = /^(?:4[0-9]{12}(?:[0-9]{3})?|5[1-5][0-9]{14})$/; // Visa, MasterCard basic check
    return regex.test(card.replace(/[\s-]/g, ""));
  }

  isAadhaar(aadhaar: string): boolean {
    const regex = /^\d{12}$/;
    return regex.test(aadhaar);
  }

  isPAN(pan: string): boolean {
    const regex = /^[A-Z]{5}[0-9]{4}[A-Z]$/;
    return regex.test(pan);
  }

  isGST(gst: string): boolean {
    const regex = /^\d{2}[A-Z]{5}\d{4}[A-Z]{1}[1-9A-Z]{1}[Z]{1}[0-9A-Z]{1}$/;
    return regex.test(gst);
  }

  isYouTubeURL(url: string): boolean {
    const regex = /^(https?:\/\/)?(www\.)?(youtube\.com|youtu\.be)\/.+$/;
    return regex.test(url);
  }

  hasValidExtension(fileName: string, allowed: string[]): boolean {
    const ext = fileName.split(".").pop()?.toLowerCase();
    return !!ext && allowed.includes(ext);
  }
}
